#!/bin/bash
# generates PRVEq_NJS_Extract_ext_q1.lean : premise-discharge witnesses for NJS_call_6 / _7 / _9 of NJS_Extract.Funs (gate L187 src)
cd "$(dirname "$0")"
O=PRVEq_NJS_Extract_ext_q1.lean
{
cat <<'H'
-- GENERATED by PCQL_mk_njs.sh. Gate: NJS_Extract.Funs (L187 closure), premises NJS_call_6 (C1_TAG), NJS_call_7 (C2_TAG), NJS_call_9 (compact.slot_offset).
-- Fresh: aspis-core emission E010 (C1_TAG, C2_TAG) and cost-probe emission E015 (slot_offset); cargo jobs 4, rustc -Zthreads=1; identity by class receipt PCWE_E003.
-- The gate has no definition of these items: they are `variable` premises. The statements below are premise-discharge witnesses (type match + value), not fresh = gate equalities.
import Aeneas
import NJS_Extract.Funs
open Aeneas Aeneas.Std Result ControlFlow Error
set_option linter.dupNamespace false
set_option linter.hashCommand false
set_option linter.unusedVariables false
set_option maxHeartbeats 1000000
set_option maxRecDepth 2048
noncomputable section
namespace PRVFreshA
H
python3 -I PCQL_slice.py inputs/fresh_E010/Funs.lean r0.merkle.C1_TAG,r0.merkle.C2_TAG 2>/dev/null
echo "end PRVFreshA"
echo "namespace PRVFreshB"
python3 -I PCQL_slice.py inputs/fresh_E015/Funs.lean compact.slot_offset 2>/dev/null
echo "end PRVFreshB"
cat <<'T'

namespace PRVEq.NJS_ext
def call6 : Result Std.U8 := ok PRVFreshA.r0.merkle.C1_TAG
def call7 : Result Std.U8 := ok PRVFreshA.r0.merkle.C2_TAG
def call9 : Std.Usize → Result Std.Usize := PRVFreshB.compact.slot_offset
theorem call6_val : call6 = ok 113#u8 := by
  delta call6 PRVFreshA.r0.merkle.C1_TAG; rfl
#print axioms call6_val
theorem call7_val : call7 = ok 241#u8 := by
  delta call7 PRVFreshA.r0.merkle.C2_TAG; rfl
#print axioms call7_val
end PRVEq.NJS_ext
T
} > $O
grep -c . $O
